//! Embedded bitmap font and Unicode width rules.
//!
//! Two flat assets hold 8-bit coverage per pixel: narrow glyphs are 8x18,
//! wide glyphs 16x18.  `font_index.rs` is generated by `tools/gen_font.py` and
//! lists codepoints in the same order as the glyphs, so a codepoint's index in
//! the array *is* its glyph index.

use crate::font_index;
use crate::unicode_tables;

/// Cell width in pixels.
pub const CELL_W: usize = 8;
/// Cell height in pixels.
pub const CELL_H: usize = 18;
/// Width of a double-cell glyph in pixels.
pub const WIDE_W: usize = 16;

pub const NARROW_GLYPH_BYTES: usize = CELL_W * CELL_H;
pub const WIDE_GLYPH_BYTES: usize = WIDE_W * CELL_H;

static NARROW_BYTES: &[u8] = include_bytes!("../assets/font8x18.bin");
static WIDE_BYTES: &[u8] = include_bytes!("../assets/font_wide8x18.bin");

/// A glyph view: coverage bytes, row-major, one byte per pixel.
#[derive(Clone, Copy, Debug)]
pub struct Glyph {
    pub width: usize,
    pub height: usize,
    pub coverage: &'static [u8],
}

impl Glyph {
    /// Coverage value for one pixel, or 0 outside the glyph.
    pub fn coverage_at(&self, x: usize, y: usize) -> u8 {
        if x >= self.width || y >= self.height {
            0
        } else {
            self.coverage[y * self.width + x]
        }
    }
}

fn lookup(table: &[u32], ch: char) -> Option<usize> {
    let cp = ch as u32;
    table.binary_search(&cp).ok()
}

/// Return the bitmap glyph for `ch`, if the bundled font has one.
pub fn glyph(ch: char) -> Option<Glyph> {
    if let Some(index) = lookup(font_index::NARROW_CODEPOINTS, ch) {
        let start = index * NARROW_GLYPH_BYTES;
        return Some(Glyph {
            width: CELL_W,
            height: CELL_H,
            coverage: &NARROW_BYTES[start..start + NARROW_GLYPH_BYTES],
        });
    }
    if let Some(index) = lookup(font_index::WIDE_CODEPOINTS, ch) {
        let start = index * WIDE_GLYPH_BYTES;
        return Some(Glyph {
            width: WIDE_W,
            height: CELL_H,
            coverage: &WIDE_BYTES[start..start + WIDE_GLYPH_BYTES],
        });
    }
    None
}

/// The `?` glyph used for an unknown narrow character.
pub fn replacement_glyph() -> Glyph {
    glyph('?').expect("the bundled font must contain '?'")
}

/// True when the codepoint is East-Asian Wide or Fullwidth.
pub fn is_wide(ch: char) -> bool {
    in_ranges(unicode_tables::WIDE, ch as u32)
}

/// True when the codepoint occupies no cell (combining mark or format control).
pub fn is_zero_width(ch: char) -> bool {
    in_ranges(unicode_tables::ZERO_WIDTH, ch as u32)
}

/// Width of a character in cells: 0 (combining/format), 2 (wide) or 1.
///
/// C0/C1 controls are 0 so a stray control never consumes a cell; the parser
/// handles them before calling this.
pub fn char_width(ch: char) -> usize {
    let cp = ch as u32;
    if cp < 0x20 || (0x7f..=0x9f).contains(&cp) {
        return 0;
    }
    if is_zero_width(ch) {
        0
    } else if is_wide(ch) {
        2
    } else {
        1
    }
}

fn in_ranges(table: &[(u32, u32)], cp: u32) -> bool {
    // Binary search for the last range whose start is <= cp.
    let mut lo = 0usize;
    let mut hi = table.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        if table[mid].0 <= cp {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo > 0 && cp <= table[lo - 1].1
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ascii_is_one_cell() {
        for ch in [' ', 'A', '~', '0'] {
            assert_eq!(char_width(ch), 1, "{ch:?}");
            assert!(glyph(ch).is_some(), "missing glyph for {ch:?}");
        }
    }

    #[test]
    fn cyrillic_and_box_drawing_have_glyphs() {
        for ch in [
            'П', 'р', 'и', 'в', 'е', 'т', '┌', '─', '┐', '█', '▓', '→', '✓',
        ] {
            assert_eq!(char_width(ch), 1, "{ch:?}");
            assert!(glyph(ch).is_some(), "missing glyph for {ch:?}");
        }
    }

    #[test]
    fn wide_and_zero_width() {
        assert_eq!(char_width('界'), 2);
        assert_eq!(char_width('あ'), 2);
        assert_eq!(char_width('Ａ'), 2);
        assert_eq!(char_width('\u{0301}'), 0); // combining acute
        assert_eq!(char_width('\u{200d}'), 0); // zero width joiner
        assert_eq!(char_width('\u{1f600}'), 2); // emoji
        assert!(glyph('界').is_some());
    }

    #[test]
    fn coverage_assets_are_consistent() {
        assert_eq!(
            NARROW_BYTES.len(),
            font_index::NARROW_CODEPOINTS.len() * NARROW_GLYPH_BYTES
        );
        assert_eq!(
            WIDE_BYTES.len(),
            font_index::WIDE_CODEPOINTS.len() * WIDE_GLYPH_BYTES
        );
        assert!(font_index::NARROW_CODEPOINTS.is_sorted());
        assert!(font_index::WIDE_CODEPOINTS.is_sorted());
    }
}
